const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const signature = String(headers['x-hub-signature-256'] || '');
let raw = item.json.rawBody || '';
if (!raw && item.binary?.data?.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
}
const appSecret = $env.META_APP_SECRET;
if (!appSecret || !raw || !signature) {
  return [{ json: { valid: false, reason: 'missing_signature_or_body' } }];
}
const expected = 'sha256=' + crypto.createHmac('sha256', appSecret).update(raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
const valid = a.length === b.length && crypto.timingSafeEqual(a, b);
let payload = null;
try { payload = JSON.parse(raw); } catch (e) { payload = null; }
return [{ json: { valid, reason: valid ? 'ok' : 'bad_signature', payload } }];

const payload = $json.payload || {};
const value = payload.entry?.[0]?.changes?.[0]?.value || {};
const message = value.messages?.[0];
if (!message) return [{ json: { skip: true, reason: 'sin_mensaje' } }];
const digitos = String(message.from || '').replace(/\D/g, '');
const e164 = digitos.length === 10 ? `+52${digitos}` : (digitos.startsWith('52') ? `+${digitos}` : `+${digitos}`);
const nombre = value.contacts?.[0]?.profile?.name || 'Contacto WhatsApp';
const texto = message.text?.body || message.type || '';
return [{ json: {
  skip: false,
  message_id: message.id,
  telefono_e164: e164,
  telefono_normalizado: digitos,
  nombre,
  texto,
  escritura: {
    webhook_eventos: "insert into public.webhook_eventos (proveedor, event_id, payload, estado, clave_idempotencia) values ('meta_whatsapp', message_id, payload, 'recibido', message_id) on conflict (clave_idempotencia) do nothing",
    prospectos: 'insert nombre, telefono E.164, origen whatsapp, ultimo_msg_cliente_at',
    leads: 'insert prospecto_id, nombre, telefono. El trigger escribe telefono_normalizado en digitos. No insertar el valor +52 en esa columna.',
    interacciones: "canal whatsapp, direccion entrante, estado recibido, contenido, id_externo = message_id. No existen message_id, origen, metadata ni direccion in."
  }
} }];
